import { validateFailure } from "../domain/autopay";
import { Reminder } from "../domain/reminder";
import { PushqClient, PushqError } from "../push/pushqClient";
import { AutopayRepository } from "../repository/autopayRepository";
import { ReminderRepository } from "../repository/reminderRepository";
import { addMinutes, compare, LocalDate, LocalDateTime } from "../time/localTime";
import { ReminderPlanner } from "./reminderPlanner";

export interface PlanResult {
  date: LocalDate;
  planned: number;
  scheduled: number;
  alreadyScheduled: number;
  skippedOptOut: number;
}

/** 알림 예약·취소와 벤더 시계 진행 */
export class ReminderService {
  private clock: LocalDateTime | undefined;

  constructor(
    private readonly planner: ReminderPlanner,
    private readonly autopays: AutopayRepository,
    private readonly reminders: ReminderRepository,
    private readonly push: PushqClient,
    private readonly retryDelayMinutes: number,
  ) {}

  now(): LocalDateTime | undefined {
    return this.clock;
  }

  /** 하루치 출금 예정 알림을 예약한다. 다시 불러도 이미 예약한 알림은 건너뛴다. */
  planDay(date: LocalDate): PlanResult {
    const plan = this.planner.billDue(date);
    let scheduled = 0;
    let already = 0;
    for (const r of plan.reminders) {
      if (this.reminders.has(r.key)) {
        already++;
        continue;
      }
      this.schedule(r);
      scheduled++;
    }
    return { date, planned: plan.reminders.length, scheduled, alreadyScheduled: already, skippedOptOut: plan.skippedOptOut };
  }

  /** 출금 실패를 기록하고 재출금 안내를 예약한다. */
  recordFailure(autopayId: string, body: unknown): { retryAt: LocalDateTime; notice?: { key: string; sendAt: LocalDateTime } } {
    const a = this.autopays.find(autopayId);
    if (!a) throw new Error(`autopay ${autopayId} not found`);
    const f = validateFailure(autopayId, body);
    this.autopays.addFailure(f);
    const retryAt = addMinutes(f.failedAt, this.retryDelayMinutes);
    const r = this.planner.retryNotice(a, retryAt);
    if (!r || this.reminders.has(r.key)) return { retryAt };
    this.schedule(r);
    return { retryAt, notice: { key: r.key, sendAt: r.sendAt } };
  }

  /** 계약 해지 — 아직 나가지 않은 알림 예약을 취소한다. */
  cancelAutopay(autopayId: string): { cancelled: number } {
    this.autopays.deactivate(autopayId);
    let cancelled = 0;
    for (const r of this.reminders.byAutopay(autopayId)) {
      if (!r.ticket || (this.clock && compare(r.sendAt, this.clock) <= 0)) continue;
      try {
        this.push.cancel(r.ticket);
        cancelled++;
      } catch (e) {
        // 이미 나간 티켓은 벤더가 E31 을 준다 — 취소할 것이 없으므로 넘어간다.
        if (!(e instanceof PushqError && e.code === "E31")) throw e;
      }
      this.reminders.remove(r.key);
    }
    return { cancelled };
  }

  /** 벤더 시계를 until 까지 진행한다(운영에서는 벤더가 스스로 흐른다). */
  advance(until: LocalDateTime): { delivered: number } {
    const delivered = this.push.advance(until);
    this.clock = until;
    return { delivered };
  }

  private schedule(r: Reminder): void {
    const ticket = this.push.schedule(r.device, r.sendAt, r.key, r.message);
    this.reminders.save({ ...r, ticket });
  }
}
import { Autopay } from "../domain/autopay";
import { Member } from "../domain/member";
import { Reminder, ReminderKind, reminderKey } from "../domain/reminder";
import { renderMessage } from "../push/messageTemplates";
import { AutopayRepository } from "../repository/autopayRepository";
import { MemberRepository } from "../repository/memberRepository";
import { SendTimePolicy } from "../scheduling/sendTime";
import { at, dateOf, dayOfMonth, LocalDate, LocalDateTime } from "../time/localTime";

export interface DayPlan {
  reminders: Reminder[];
  skippedOptOut: number;
}

/** 어떤 알림을 언제 보낼지 정한다(예약은 하지 않는다). */
export class ReminderPlanner {
  constructor(
    private readonly members: MemberRepository,
    private readonly autopays: AutopayRepository,
    private readonly policy: SendTimePolicy,
    private readonly retryNoticeLeadMinutes: number,
  ) {}

  /** 그날 출금되는 계약마다 출금 예정 알림 1건 */
  billDue(date: LocalDate): DayPlan {
    const reminders: Reminder[] = [];
    let skippedOptOut = 0;
    const seen = new Set<string>();
    for (const a of this.autopays.billingOn(dayOfMonth(date))) {
      const m = this.members.find(a.memberId);
      if (!m) continue;
      if (!m.pushOptIn) {
        skippedOptOut++;
        continue;
      }
      const dueAt = at(date, a.billingTime);
      const r = this.build("BILL_DUE", a, m, dueAt, m.leadMinutes);
      if (seen.has(r.key)) continue;
      seen.add(r.key);
      reminders.push(r);
    }
    return { reminders, skippedOptOut };
  }

  /** 출금 실패 → 재출금 안내 1건(수신 거부면 없음) */
  retryNotice(autopay: Autopay, retryAt: LocalDateTime): Reminder | undefined {
    const m = this.members.find(autopay.memberId);
    if (!m || !m.pushOptIn) return undefined;
    return this.build("RETRY", autopay, m, retryAt, this.retryNoticeLeadMinutes);
  }

  private build(kind: ReminderKind, a: Autopay, m: Member, dueAt: LocalDateTime, lead: number): Reminder {
    return {
      key: reminderKey(kind, a.id, dueAt),
      kind,
      memberId: m.id,
      autopayId: a.id,
      device: m.device,
      dueAt,
      sendAt: this.policy.sendAt(dueAt, lead),
      planDate: dateOf(dueAt),
      message: renderMessage(kind, a, dueAt),
    };
  }
}
import { LocalDate, LocalDateTime } from "../time/localTime";

export type ReminderKind = "BILL_DUE" | "RETRY";

export const KIND_LABEL: Record<ReminderKind, string> = {
  BILL_DUE: "출금 예정",
  RETRY: "재출금 안내",
};

const KIND_CODE: Record<ReminderKind, string> = {
  BILL_DUE: "due",
  RETRY: "retry",
};

export interface Reminder {
  /** 푸시 태그로도 쓰는 업무 키 — 같은 알림은 늘 같은 키 */
  key: string;
  kind: ReminderKind;
  memberId: string;
  autopayId: string;
  device: string;
  /** 이 알림이 안내하는 출금(또는 재출금) 시각 */
  dueAt: LocalDateTime;
  /** 실제 발송 예약 시각 */
  sendAt: LocalDateTime;
  /** 리포트 묶음 기준일(= 출금일) */
  planDate: LocalDate;
  message: string;
  ticket?: string;
}

// 재출금 안내도 출금 예정 알림처럼 계약·날짜 단위 키다(1.9.0부터).
// TODO: 하루 두 번째 재출금 안내까지 막히는데 아직 날짜 단위여야 하나?
export function reminderKey(kind: ReminderKind, autopayId: string, dueAt: LocalDateTime): string {
  return `rmd.${autopayId}.${KIND_CODE[kind]}.${dueAt.slice(0, 10).replace(/-/g, "")}`;
}
import { isLocalDateTime, LocalDateTime } from "../time/localTime";

/** 자동이체(정기 출금) 계약 — 가맹점이 정한 날·시각에 출금된다. */
export interface Autopay {
  id: string;
  memberId: string;
  merchant: string;
  amount: number;
  /** 매월 출금일(1~28) */
  billingDay: number;
  /** 가맹점 출금 배치 시각 "HH:MM" */
  billingTime: string;
  active: boolean;
}

/** 출금 실패 기록 — 재출금은 실패 처리 시각 기준으로 잡힌다. */
export interface BillingFailure {
  autopayId: string;
  failedAt: LocalDateTime;
  reason: string;
}

export function validateAutopay(input: unknown): Omit<Autopay, "id" | "active"> {
  const b = (input ?? {}) as Record<string, unknown>;
  if (typeof b.memberId !== "string") throw new Error("memberId required");
  if (typeof b.merchant !== "string" || b.merchant.trim() === "") throw new Error("merchant required");
  if (typeof b.amount !== "number" || !Number.isInteger(b.amount) || b.amount <= 0) throw new Error("amount must be a positive integer (KRW)");
  if (typeof b.billingDay !== "number" || !Number.isInteger(b.billingDay) || b.billingDay < 1 || b.billingDay > 28) {
    throw new Error("billingDay must be 1..28");
  }
  if (typeof b.billingTime !== "string" || !/^([01]\d|2[0-3]):[0-5]\d$/.test(b.billingTime)) throw new Error("billingTime must be HH:MM");
  return { memberId: b.memberId, merchant: b.merchant.trim(), amount: b.amount, billingDay: b.billingDay, billingTime: b.billingTime };
}

export function validateFailure(autopayId: string, input: unknown): BillingFailure {
  const b = (input ?? {}) as Record<string, unknown>;
  if (!isLocalDateTime(b.failedAt)) throw new Error("failedAt must be YYYY-MM-DDTHH:MM:SS");
  const reason = typeof b.reason === "string" && b.reason !== "" ? b.reason : "INSUFFICIENT_BALANCE";
  return { autopayId, failedAt: b.failedAt, reason };
}
import { Reminder } from "../domain/reminder";
import { LocalDate } from "../time/localTime";

/** 예약해 둔 알림 — 키 단위로 한 번만 저장된다. */
export class ReminderRepository {
  private readonly rows = new Map<string, Reminder>();

  has(key: string): boolean {
    return this.rows.has(key);
  }

  save(r: Reminder): void {
    this.rows.set(r.key, { ...r });
  }

  find(key: string): Reminder | undefined {
    const r = this.rows.get(key);
    return r ? { ...r } : undefined;
  }

  byPlanDate(date: LocalDate): Reminder[] {
    return [...this.rows.values()]
      .filter((r) => r.planDate === date)
      .sort((a, b) => (a.sendAt < b.sendAt ? -1 : a.sendAt > b.sendAt ? 1 : a.key < b.key ? -1 : 1))
      .map((r) => ({ ...r }));
  }

  byAutopay(autopayId: string): Reminder[] {
    return [...this.rows.values()].filter((r) => r.autopayId === autopayId).map((r) => ({ ...r }));
  }

  remove(key: string): void {
    this.rows.delete(key);
  }
}
import { KIND_LABEL } from "../domain/reminder";
import { maskDevice } from "../push/deviceToken";
import { DeliveredPush, PushqClient } from "../push/pushqClient";
import { ReminderRepository } from "../repository/reminderRepository";
import { compare, LocalDate, LocalDateTime } from "../time/localTime";

export type LineStatus = "발송" | "미발송" | "예약";

export interface ReportLine {
  key: string;
  memberId: string;
  kind: string;
  dueAt: LocalDateTime;
  sendAt: LocalDateTime;
  ticket: string;
  device: string;
  status: LineStatus;
  deliveredAt?: LocalDateTime;
}

export interface ReminderReport {
  date: LocalDate;
  asOf: LocalDateTime | null;
  planned: number;
  delivered: number;
  missing: number;
  pending: number;
  lines: ReportLine[];
  text: string;
}

/** 출금일 기준 알림 발송 현황 — 운영 화면용 */
export class ReminderReportBuilder {
  constructor(private readonly reminders: ReminderRepository, private readonly push: PushqClient) {}

  build(date: LocalDate, asOf: LocalDateTime | undefined): ReminderReport {
    const byTag = new Map<string, DeliveredPush>();
    for (const d of this.push.delivered()) if (!byTag.has(d.tag)) byTag.set(d.tag, d);

    const lines: ReportLine[] = this.reminders.byPlanDate(date).map((r) => {
      const hit = byTag.get(r.key);
      let status: LineStatus;
      if (hit) status = "발송";
      else if (asOf && compare(r.sendAt, asOf) <= 0) status = "미발송";
      else status = "예약";
      return {
        key: r.key,
        memberId: r.memberId,
        kind: KIND_LABEL[r.kind],
        dueAt: r.dueAt,
        sendAt: r.sendAt,
        ticket: r.ticket ?? "-",
        device: maskDevice(r.device),
        status,
        deliveredAt: hit?.at,
      };
    });
    const count = (s: LineStatus) => lines.filter((l) => l.status === s).length;
    const planned = lines.length;
    const delivered = count("발송");
    const missing = count("미발송");
    const pending = count("예약");
    return {
      date,
      asOf: asOf ?? null,
      planned,
      delivered,
      missing,
      pending,
      lines,
      text: `${date} 알림 — 예약 ${planned} / 발송 ${delivered} / 미발송 ${missing} / 대기 ${pending}`,
    };
  }
}
import { mkdtempSync, rmSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";
import { App, createApp } from "../src/app";
import { assert, eq, onCleanup, run, test } from "./harness";

interface Report {
  planned: number;
  delivered: number;
  missing: number;
  pending: number;
  lines: { key: string; memberId: string; kind: string; status: string; sendAt: string }[];
  text: string;
}

interface Notifications {
  memberId: string;
  notifications: { at: string; tag: string; message: string }[];
}

/** 빈 pushq 상태 디렉토리를 가진 앱 하나 */
function world() {
  const home = mkdtempSync(join(tmpdir(), "autopay-rmd-"));
  onCleanup(() => rmSync(home, { recursive: true, force: true }));
  const app: App = createApp({ pushqHome: home, pushqBin: join(process.cwd(), "vendor", "bin", "pushq") });

  const call = (method: string, url: string, body?: unknown): unknown => {
    const r = app.handle(method, url, body);
    eq(r.status, 200, `${method} ${url} → ${JSON.stringify(r.body)}`);
    return r.body;
  };

  return {
    member(id: string, name: string, device: string, leadMinutes: number, pushOptIn = true): void {
      call("POST", "/members", { id, name, device, leadMinutes, pushOptIn });
    },
    autopay(memberId: string, merchant: string, amount: number, billingDay: number, billingTime: string): string {
      return (call("POST", "/autopays", { memberId, merchant, amount, billingDay, billingTime }) as { id: string }).id;
    },
    plan(date: string): { planned: number; scheduled: number; alreadyScheduled: number; skippedOptOut: number } {
      return call("POST", "/reminders/plan", { date }) as { planned: number; scheduled: number; alreadyScheduled: number; skippedOptOut: number };
    },
    fail(autopayId: string, failedAt: string): void {
      call("POST", `/autopays/${autopayId}/failures`, { failedAt });
    },
    cancel(autopayId: string): void {
      call("POST", `/autopays/${autopayId}/cancel`);
    },
    clock(until: string): void {
      call("POST", "/clock", { until });
    },
    report(date: string): Report {
      return call("GET", `/reports/reminders/${date}`) as Report;
    },
    inbox(memberId: string): Notifications["notifications"] {
      return (call("GET", `/members/${memberId}/notifications`) as Notifications).notifications;
    },
  };
}

test("every autopay customer gets the withdrawal reminder in time on billing day", () => {
  const w = world();
  w.member("M1001", "김하늘", "ios:Hb7cQ2xk91ZpA", 30);
  w.member("M1002", "이도윤", "and:fT0p3LmQw8eR", 60);
  w.member("M1003", "박서연", " IOS:Zx81kQpLm0Ty ", 30);
  w.member("M1004", "최민준", "and:Pq19sXkLm2Vb", 10);
  w.member("M1005", "정지우", "ios:Nn41tRe7Ku3Q", 1440);

  const phone = w.autopay("M1001", "한빛모바일 통신요금", 55000, 12, "08:00");
  w.autopay("M1002", "든든손해보험", 89000, 12, "10:20");
  w.autopay("M1003", "스트림플러스 구독", 13900, 12, "13:47");
  w.autopay("M1004", "푸른마을 관리비", 187420, 12, "18:33");
  w.autopay("M1005", "새싹수학학원", 320000, 12, "09:00");

  const plan = w.plan("2026-10-12");
  eq([plan.planned, plan.scheduled], [5, 5], "reminders planned for the 12th");

  // 08:00 출금이 잔액 부족으로 실패 → 2시간 뒤 재출금, 그 30분 전에 안내
  w.clock("2026-10-12T08:00:37");
  w.fail(phone, "2026-10-12T08:00:37");
  w.clock("2026-10-12T23:59:00");

  const r = w.report("2026-10-12");
  eq(r.lines.filter((l) => l.status !== "발송").map((l) => `${l.memberId} ${l.kind}`), [], "reminders not delivered");
  eq([r.planned, r.delivered, r.missing], [6, 6, 0], `report counts (${r.text})`);

  // 고객이 설정한 시점보다 늦게 도착하면 안 된다
  const latest: [string, string[], string][] = [
    ["M1001", ["2026-10-12T07:30:00", "2026-10-12T09:30:37"], "한빛모바일"],
    ["M1002", ["2026-10-12T09:20:00"], "든든손해보험"],
    ["M1003", ["2026-10-12T13:17:00"], "스트림플러스"],
    ["M1004", ["2026-10-12T18:23:00"], "푸른마을"],
    ["M1005", ["2026-10-11T09:00:00"], "새싹수학학원"],
  ];
  for (const [id, deadlines, merchant] of latest) {
    const inbox = w.inbox(id);
    eq(inbox.length, deadlines.length, `pushes received by ${id}`);
    inbox.forEach((n, i) => {
      assert(n.at <= deadlines[i], `${id} push #${i + 1} arrived at ${n.at}, later than ${deadlines[i]}`);
      assert(n.message.includes(merchant), `${id} push mentions ${merchant}`);
    });
  }
});

test("a retry that fails again gets its own notice before the second retry", () => {
  const w = world();
  w.member("M4001", "강예린", "ios:Rt55uV66wW77", 30);
  const gas = w.autopay("M4001", "도시가스 요금", 48200, 15, "08:00");
  w.plan("2026-10-15");

  w.clock("2026-10-15T08:00:41");
  w.fail(gas, "2026-10-15T08:00:41"); // 재출금 10:00:41
  w.clock("2026-10-15T10:01:12");
  w.fail(gas, "2026-10-15T10:01:12"); // 재출금도 실패 → 2차 재출금 12:01:12
  w.clock("2026-10-15T23:00:00");

  const inbox = w.inbox("M4001");
  eq(inbox.length, 3, "withdrawal reminder + two retry notices");
  const deadlines = ["2026-10-15T07:30:00", "2026-10-15T09:30:41", "2026-10-15T11:31:12"];
  inbox.forEach((n, i) => assert(n.at <= deadlines[i], `push #${i + 1} arrived at ${n.at}, later than ${deadlines[i]}`));
  assert(inbox[1].message.includes("10:00"), `first retry notice names 10:00: ${inbox[1].message}`);
  assert(inbox[2].message.includes("12:01"), `second retry notice names 12:01: ${inbox[2].message}`);

  const r = w.report("2026-10-15");
  eq([r.planned, r.delivered, r.missing], [3, 3, 0], `report counts (${r.text})`);
  eq(r.lines.filter((l) => l.kind === "재출금 안내").length, 2, "retry notice lines");
});

test("customers who turned pushes off are skipped and counted", () => {
  const w = world();
  w.member("M2001", "한지민", "ios:Aa11bB22cC33", 30);
  w.member("M2002", "오세훈", "and:Dd44eE55fF66", 30, false);
  w.autopay("M2001", "든든손해보험", 42000, 3, "09:00");
  w.autopay("M2002", "든든손해보험", 42000, 3, "09:00");
  const plan = w.plan("2026-11-03");
  eq([plan.planned, plan.skippedOptOut], [1, 1], "planned / opted out");
  w.clock("2026-11-03T12:00:00");
  eq(w.inbox("M2001").length, 1, "opted-in customer");
  eq(w.inbox("M2002"), [], "opted-out customer");
});

test("planning the same day twice does not double-book, and cancelled contracts stay quiet", () => {
  const w = world();
  w.member("M3001", "서지호", "ios:Gg77hH88iI99", 60);
  w.member("M3002", "윤시우", "and:Jj00kK11lL22", 30);
  w.autopay("M3001", "한빛모바일 통신요금", 61000, 20, "11:00");
  const gym = w.autopay("M3002", "바른필라테스", 99000, 20, "07:30");
  eq(w.plan("2026-10-20").scheduled, 2, "first planning");
  const again = w.plan("2026-10-20");
  eq([again.scheduled, again.alreadyScheduled], [0, 2], "second planning");
  w.cancel(gym);
  w.clock("2026-10-20T23:00:00");
  eq(w.inbox("M3001").length, 1, "one reminder, not two");
  eq(w.inbox("M3002"), [], "cancelled contract");
});

run();

